\title{Sharp Exponent Lower Bounds for Sumsets in Intervals and Boxes of $\Z^d$}
\author{Aristotle}
\date{2026-07-14}

\begin{document}
\maketitle

\begin{abstract}
Given finite nonempty sets $A_1,\dots,A_n$ of integers contained in the segment
$\{0,1,\dots,m\}$, we determine the sharp exponent $p$ for which
$\bigl(\abs{A_1}\cdots\abs{A_n}\bigr)^{1/p}\le\abs{A_1+\dots+A_n}$ holds for
\emph{every} such configuration. The exponent is the transcendental quantity
$p=p(n,m)=n\log(m+1)/\log(nm+1)$, which strictly improves the classical
geometric-mean exponent $n$ whenever $n\ge2$ and is attained with equality by the
full interval $A_j=\{0,\dots,m\}$, proving optimality. The proof combines the
iterated Cauchy--Davenport inequality (valid in any torsion-free abelian group)
with a real-analysis inequality derived from the arithmetic--geometric mean
inequality and a concavity chord estimate. Because the additive engine holds in
arbitrary torsion-free abelian groups, we obtain a general bound with exponent
$q(n,M)=n\log M/\log(1+n(M-1))$ under a uniform cap $\abs{A_j}\le M$, and its
specialization to the box $\{0,\dots,m\}^d\subseteq\Z^d$ (with $M=(m+1)^d$). The
one-dimensional case is recovered exactly since $q(n,m+1)=p(n,m)$. The box
exponent always dominates the geometric-mean bound but is \emph{not} sharp for
$d\ge2$; isolating the sharp higher-dimensional exponent is the main open problem.
\end{abstract}

\section{Introduction}

Additive combinatorics studies how the size of a set behaves under addition. For
an abelian group $G$ and finite $A,B\subseteq G$, the \emph{sumset} is
$A+B=\{a+b:a\in A,\ b\in B\}$, and for a family $A_1,\dots,A_n$,
$\sum_{j=1}^n A_j=\{a_1+\dots+a_n:a_j\in A_j\}$. The inverse question asks: given
the cardinalities $\abs{A_j}$, how small can $\bigl|\sum_j A_j\bigr|$ be? A small
sumset signals strong additive structure.

Two classical bounds frame the problem: the trivial
$\bigl|\sum_j A_j\bigr|\ge\max_j\abs{A_j}$, and the geometric-mean bound
$\bigl|\sum_j A_j\bigr|\ge\bigl(\abs{A_1}\cdots\abs{A_n}\bigr)^{1/n}$. The latter
is loose: the maximally redundant configuration --- every $A_j$ the full interval
$\{0,\dots,m\}$ --- leaves a large gap. This paper resolves the one-dimensional
problem exactly, identifying the sharp exponent $p(n,m)$, and lifts the additive
machinery to torsion-free abelian groups, yielding a valid (non-sharp) box bound
in $\Z^d$.

\section{Preliminaries}

Throughout, $n\ge1$, $m\ge1$, and $\log$ is the natural logarithm; all sets are
finite and nonempty.

\begin{definition}[Interval and box]
The discrete segment is $I_m=\{0,1,\dots,m\}\subseteq\Z$, with $\abs{I_m}=m+1$.
The box is $B_{d,m}=\{0,1,\dots,m\}^d\subseteq\Z^d$, with $\abs{B_{d,m}}=(m+1)^d$.
The discrete $L_1$-ball of radius $m$ is
$\{x\in\Z^d:\abs{x_1}+\dots+\abs{x_d}\le m\}$; the segment $I_m$ is its
one-dimensional face.
\end{definition}

\begin{definition}[Torsion-free abelian group]
An abelian group $G$ is torsion-free if $kx=0$ with $k\in\Z_{>0}$ forces $x=0$.
Examples: $\Z$, $\Z^d$, $\mathbb{Q}$.
\end{definition}

\section{The exponents}

\begin{definition}\label{def:p}
For $n,m\ge1$, $\displaystyle p(n,m)=\frac{n\log(m+1)}{\log(nm+1)}$.
\end{definition}

\begin{definition}\label{def:q}
For $n\ge1$ and real $M>1$,
$\displaystyle q(n,M)=\frac{n\log M}{\log\bigl(1+n(M-1)\bigr)}$.
\end{definition}

\begin{proposition}[Compatibility]\label{prop:compat}
For all $n,m$, $q(n,m+1)=p(n,m)$.
\end{proposition}
\begin{proof}
Substituting $M=m+1$ gives $1+n(M-1)=nm+1$ and $\log M=\log(m+1)$.
\end{proof}

\begin{proposition}[Positivity]\label{prop:pos}
If $n\ge1$ and $M>1$ then $q(n,M)>0$; in particular $p(n,m)>0$.
\end{proposition}
\begin{proof}
$n\log M>0$; and $1+n(M-1)>1$ so $\log(1+n(M-1))>0$.
\end{proof}

\begin{proposition}[Domination]\label{prop:dom}
If $n\ge1$ and $M>1$ then $q(n,M)\le n$, hence $p(n,m)\le n$.
\end{proposition}
\begin{proof}
Since $M\le1+n(M-1)$, monotonicity of $\log$ gives
$\log M\le\log(1+n(M-1))$; multiply by $n$ and divide by the positive denominator.
\end{proof}

Because $p\le n$ and $\prod_j\abs{A_j}\ge1$, the exponent $1/p\ge1/n$, so the
sharp bound is at least as strong as the geometric-mean bound, strictly so for
$n\ge2$.

\section{The general group-theoretic bound}

\begin{lemma}[Concavity chord estimate]\label{lem:chord}
Let $1<M\le L$ and $1\le u\le L$, and set $\beta=\log M/\log L\in(0,1]$. Then
$\displaystyle 1+\frac{(u-1)(M-1)}{L-1}\le u^{\beta}$.
\end{lemma}
\begin{proof}[Proof sketch]
The map $t\mapsto t^{\beta}$ is concave on $[0,\infty)$ for $\beta\in[0,1]$, so it
lies above the chord joining $(1,1^\beta)=(1,1)$ and $(L,L^\beta)=(L,M)$ (the last
equality is the definition of $\beta$). Writing
$u=\frac{L-u}{L-1}\cdot1+\frac{u-1}{L-1}\cdot L$ and applying concavity yields
$u^\beta\ge\frac{L-u}{L-1}+\frac{u-1}{L-1}M=1+(u-1)(M-1)/(L-1)$.
\end{proof}

\begin{lemma}[AM--GM, power form]\label{lem:amgm}
For nonnegative reals $a_1,\dots,a_n$,
$\displaystyle\prod_{j=1}^n a_j\le\Bigl(\tfrac1n\sum_{j=1}^n a_j\Bigr)^{n}$.
\end{lemma}
\begin{proof}[Proof sketch]
Weighted AM--GM with uniform weights $1/n$ gives
$\prod_j a_j^{1/n}\le\frac1n\sum_j a_j$; raise to the $n$-th power.
\end{proof}

\begin{lemma}[Product bound]\label{lem:prod}
Let $n\ge1$, $M>1$, and $a_1,\dots,a_n\in[1,M]$. With $T=\sum_j(a_j-1)\ge0$,
$\displaystyle\prod_{j=1}^n a_j\le(1+T)^{\,q(n,M)}$.
\end{lemma}
\begin{proof}[Proof sketch]
Put $L=1+n(M-1)$, $\beta=\log M/\log L$, so $n\beta=q(n,M)$. By
Lemma~\ref{lem:amgm}, $\prod_j a_j\le\bigl((T+n)/n\bigr)^n=(1+T/n)^n$. As each
$a_j\le M$, $T\le n(M-1)=L-1$, so $u:=1+T\in[1,L]$; Lemma~\ref{lem:chord} gives
$1+T/n\le(1+T)^\beta$ (the left side simplifies from
$1+(u-1)(M-1)/(L-1)$). Raise to the $n$-th power:
$(1+T/n)^n\le(1+T)^{n\beta}=(1+T)^{q(n,M)}$.
\end{proof}

\begin{lemma}[Iterated Cauchy--Davenport]\label{lem:cd}
Let $G$ be a torsion-free abelian group and $A_1,\dots,A_n\subseteq G$ finite
nonempty. Then $\displaystyle\Bigl|\sum_{j=1}^n A_j\Bigr|\ge1+\sum_{j=1}^n(\abs{A_j}-1)$.
\end{lemma}
\begin{proof}[Proof sketch]
The two-set case $\abs{A+B}\ge\abs{A}+\abs{B}-1$ holds in any torsion-free abelian
group. Induct on $n$: with $S=\sum_{j<n}A_j$ nonempty,
$\abs{S+A_n}\ge\abs{S}+\abs{A_n}-1$.
\end{proof}

\begin{theorem}[General sumset lower bound]\label{thm:general}
Let $G$ be a torsion-free abelian group, $n\ge1$, $M>1$, and
$A_1,\dots,A_n\subseteq G$ finite nonempty with $\abs{A_j}\le M$. Then
$\displaystyle\prod_{j=1}^n\abs{A_j}\le\Bigl|\sum_{j=1}^n A_j\Bigr|^{\,q(n,M)}$,
and equivalently
$\bigl(\prod_j\abs{A_j}\bigr)^{1/q(n,M)}\le\bigl|\sum_j A_j\bigr|$.
\end{theorem}
\begin{proof}
Apply Lemma~\ref{lem:prod} with $a_j=\abs{A_j}\in[1,M]$ to get
$\prod_j\abs{A_j}\le(1+T)^{q(n,M)}$, $T=\sum_j(\abs{A_j}-1)$. By
Lemma~\ref{lem:cd}, $1+T\le\bigl|\sum_j A_j\bigr|$; since $q(n,M)>0$
(Proposition~\ref{prop:pos}) and both sides are $\ge1$, monotonicity of
$t\mapsto t^q$ finishes the first inequality. Raising to $1/q(n,M)$ gives the
root form.
\end{proof}

\section{The sharp one-dimensional bound}

\begin{theorem}[Sharp sumset lower bound, dimension one]\label{thm:dim1}
Let $n,m\ge1$ and $A_1,\dots,A_n\subseteq\{0,1,\dots,m\}\subseteq\Z$ finite
nonempty. Then
$\displaystyle\Bigl(\prod_{j=1}^n\abs{A_j}\Bigr)^{1/p(n,m)}\le\Bigl|\sum_{j=1}^n A_j\Bigr|$,
with $p(n,m)=n\log(m+1)/\log(nm+1)$.
\end{theorem}
\begin{proof}
Each $\abs{A_j}\le m+1=:M>1$. Apply Theorem~\ref{thm:general} in $G=\Z$; by
Proposition~\ref{prop:compat}, $q(n,m+1)=p(n,m)$.
\end{proof}

\section{Optimality}

\begin{lemma}[Sumset of an interval]\label{lem:nfold}
For $n\ge1$, $m\ge0$, the $n$-fold sumset of $I_m=\{0,\dots,m\}$ is
$\{0,1,\dots,nm\}$, of cardinality $nm+1$.
\end{lemma}
\begin{proof}[Proof sketch]
Induction, using $\{0,\dots,a\}+\{0,\dots,b\}=\{0,\dots,a+b\}$.
\end{proof}

\begin{theorem}[Extremal equality and sharpness]\label{thm:extremal}
For $n,m\ge1$, taking every $A_j=I_m$ yields equality in
Theorem~\ref{thm:dim1}:
$\bigl(\prod_j\abs{I_m}\bigr)^{1/p(n,m)}=\bigl|\sum_j I_m\bigr|$. Consequently no
exponent smaller than $p(n,m)$ is valid for all configurations.
\end{theorem}
\begin{proof}
Here $\prod_j\abs{I_m}=(m+1)^n$ and, by Lemma~\ref{lem:nfold},
$\bigl|\sum_j I_m\bigr|=nm+1$. The identity $(m+1)^{n/p}=nm+1$ is equivalent (take
logs) to $p=n\log(m+1)/\log(nm+1)$, i.e.\ Definition~\ref{def:p}. If some
$p'<p$ worked for all configurations, then
$\bigl((m+1)^n\bigr)^{1/p'}>\bigl((m+1)^n\bigr)^{1/p}=nm+1$, contradicting the
bound at $A_j=I_m$.
\end{proof}

\begin{theorem}[Packaged sharpness]\label{thm:package}
For $n,m\ge1$ and finite nonempty $A_j\subseteq\{0,\dots,m\}$:
(i) $\bigl(\prod_j\abs{A_j}\bigr)^{1/p}\le\bigl|\sum_j A_j\bigr|$;
(ii) equality holds at $A_j=\{0,\dots,m\}$;
(iii) $p\le n$. Hence $p=p(n,m)$ is the sharp exponent.
\end{theorem}

\section{Higher dimensions}

\begin{theorem}[Box bound in $\Z^d$]\label{thm:box}
Let $d,n,m\ge1$ and $A_1,\dots,A_n\subseteq B_{d,m}=\{0,\dots,m\}^d\subseteq\Z^d$
finite nonempty. Then
$\displaystyle\prod_{j=1}^n\abs{A_j}\le\Bigl|\sum_{j=1}^n A_j\Bigr|^{\,q(n,(m+1)^d)}$,
equivalently
$\bigl(\prod_j\abs{A_j}\bigr)^{1/q(n,(m+1)^d)}\le\bigl|\sum_j A_j\bigr|$.
Moreover $q(n,(m+1)^d)\le n$, and for $d=1$ the exponent equals $p(n,m)$.
\end{theorem}
\begin{proof}
$\Z^d$ is torsion-free abelian and $\abs{B_{d,m}}=(m+1)^d=:M>1$, so
$\abs{A_j}\le M$. Apply Theorem~\ref{thm:general}. Domination is
Proposition~\ref{prop:dom}; the $d=1$ identity is Proposition~\ref{prop:compat}.
\end{proof}

\subsection{Non-sharpness for $d\ge2$}

The exponent $q(n,(m+1)^d)$ is valid but not sharp for $d\ge2$. The slack enters
at Lemma~\ref{lem:cd}: the Cauchy--Davenport step is tight only for
one-dimensional arithmetic-progression-like sets. A box $\{0,\dots,m\}^2$ has
$n$-fold sumset $\{0,\dots,nm\}^2$ of size $(nm+1)^2$, whereas
Lemma~\ref{lem:cd} guarantees only linear-in-$n$ growth. Determining the sharp
higher-dimensional exponent is the principal open problem.

\section{Discussion and future work}

In dimension one the picture is complete: $p(n,m)$ is the exact threshold
exponent, with the interval as extremiser. Open problems include:
\begin{enumerate}
  \item \textbf{Sharp higher-dimensional exponent.} Find the sharp $p$-exponent
  for $A_j\subseteq\{0,\dots,m\}^d$ or the $L_1$-ball for $d\ge2$; a
  tensor-power/compression or Pl\"unnecke--Ruzsa argument likely replaces the
  one-dimensional Cauchy--Davenport step.
  \item \textbf{Translated/dilated intervals.} Extend extremiser optimality to
  arbitrary arithmetic progressions.
  \item \textbf{Asymmetric version.} Seek refinements when the $\abs{A_j}$ differ
  widely.
  \item \textbf{Stability.} Quantify how close to the extremal interval a
  near-extremal configuration must be.
\end{enumerate}

\section{Conclusion}

We identified the sharp exponent $p(n,m)=n\log(m+1)/\log(nm+1)$ for sumset lower
bounds on integer intervals, proved it for all configurations, and established
optimality via the extremal interval. Lifting the additive engine to
torsion-free abelian groups produced a general bound with exponent $q(n,M)$ and
its specialization to boxes in $\Z^d$, which dominates the geometric-mean bound
in every dimension but is sharp only for $d=1$.

\end{document}

