"""Sharp vs. geometric-mean exponent, and the compatibility identity."""
import math

def p_exp(n: int, m: int) -> float:
    return n * math.log(m + 1) / math.log(n * m + 1)

def q_exp(n: int, M: float) -> float:
    return n * math.log(M) / math.log(1 + n * (M - 1))

def main() -> None:
    print(f"{'n':>3}{'m':>4}{'p(n,m)':>12}{'n':>5}")
    for n in (2, 3, 5, 10):
        for m in (1, 3, 10):
            print(f"{n:>3}{m:>4}{p_exp(n, m):>12.6f}{n:>5}")
    # q(n, m+1) == p(n, m)
    for n in (2, 4, 7):
        for m in (1, 5, 12):
            assert abs(q_exp(n, m + 1) - p_exp(n, m)) < 1e-12
    print("compatibility q(n,m+1)=p(n,m) verified")

if __name__ == "__main__":
    main()

"""Random verification that (prod|A_j|)^{1/p} <= |sum A_j| in dimension one."""
import math, random
from typing import Iterable, List, Sequence

def p_exp(n: int, m: int) -> float:
    return n * math.log(m + 1) / math.log(n * m + 1)

def sumset_1d(sets: Sequence[Iterable[int]]) -> set:
    acc = {0}
    for A in sets:
        acc = {a + b for a in acc for b in A}
    return acc

def main(trials: int = 5000, seed: int = 20260714) -> None:
    rng = random.Random(seed)
    worst = math.inf
    for _ in range(trials):
        n, m = rng.randint(1, 4), rng.randint(1, 8)
        universe = list(range(m + 1))
        sets: List[List[int]] = [rng.sample(universe, rng.randint(1, m + 1))
                                 for _ in range(n)]
        actual = len(sumset_1d(sets))
        floor = math.prod(len(A) for A in sets) ** (1.0 / p_exp(n, m))
        worst = min(worst, actual / floor)
    print(f"trials={trials}  tightest actual/floor={worst:.6f}  (>=1 required)")
    assert worst >= 1 - 1e-9

if __name__ == "__main__":
    main()

"""Extremal interval {0,...,m} attains equality; box bound is loose for d>=2."""
import itertools, math
from typing import Iterable, Sequence, Tuple

def p_exp(n: int, m: int) -> float:
    return n * math.log(m + 1) / math.log(n * m + 1)

def q_exp(n: int, M: float) -> float:
    return n * math.log(M) / math.log(1 + n * (M - 1))

def sumset_nd(sets: Sequence[Iterable[Tuple[int, ...]]]) -> set:
    it = iter(sets); acc = set(next(it))
    for A in it:
        acc = {tuple(x + y for x, y in zip(a, b)) for a in acc for b in A}
    return acc

def main() -> None:
    # 1D equality
    for n in (2, 3, 5):
        for m in (2, 4, 9):
            floor = ((m + 1) ** n) ** (1.0 / p_exp(n, m))
            print(f"1D n={n} m={m}: floor={floor:.4f} expected={n*m+1}")
    # 2D box slack
    for d, n, m in [(2, 2, 2), (2, 3, 2)]:
        axis = range(m + 1)
        box = [tuple(pt) for pt in itertools.product(axis, repeat=d)]
        actual = len(sumset_nd([box] * n))
        floor = (len(box) ** n) ** (1.0 / q_exp(n, (m + 1) ** d))
        print(f"box d={d} n={n} m={m}: actual={actual} floor={floor:.3f} "
              f"slack={actual/floor:.3f}")

if __name__ == "__main__":
    main()

