import math

def sharp_exponent(n: int, m: int) -> float:
    """Return the sharp one-dimensional exponent p(n, m)."""
    return n * math.log(m + 1) / math.log(n * m + 1)

def box_exponent(n: int, m: int, d: int) -> float:
    """Return the higher-dimensional box exponent q(n, (m+1)^d)."""
    M = (m + 1) ** d
    return n * math.log(M) / math.log(1 + n * (M - 1))

