function CERTIFIED_LOWER_BOUNDS(sizes[1..n], M):
    prod <- product of sizes
    q <- n * ln(M) / ln(1 + n*(M - 1))
    cd <- 1 + sum_j (sizes[j] - 1)
    gm <- prod^(1/n)
    sharp <- prod^(1/q)
    return {cd, gm, sharp}

function BEST_FLOOR(sizes, M):
    return max(CERTIFIED_LOWER_BOUNDS(sizes, M))

function ITERATED_MINKOWSKI(sets):
    acc <- {0}            # or the first set for Z^d
    for A in sets:
        acc <- { a + b : a in acc, b in A }
    return acc

function VERIFY_BOUND_1D(sets, m):
    sizes <- [ |A| : A in sets ]
    p <- SHARP_EXPONENT(|sets|, m)
    actual <- |ITERATED_MINKOWSKI(sets)|
    floor <- (product of sizes)^(1/p)
    return (actual, floor, actual >= floor)

