from typing import Iterable, List, Sequence, Tuple

def iterated_minkowski_1d(sets: Sequence[Iterable[int]]) -> set:
    """Exact n-fold Minkowski sum of integer sets by iterated pairwise sums."""
    acc = {0}
    for A in sets:
        acc = {a + b for a in acc for b in A}
    return acc

def iterated_minkowski_nd(sets: Sequence[Iterable[Tuple[int, ...]]]) -> set:
    """Exact n-fold Minkowski sum of lattice-point sets in Z^d."""
    it = iter(sets)
    acc = set(next(it))
    for A in it:
        acc = {tuple(x + y for x, y in zip(a, b)) for a in acc for b in A}
    return acc

def verify_bound_1d(sets: Sequence[Iterable[int]], m: int) -> Tuple[int, float, bool]:
    """Compute the exact sumset size, the certified sharp floor, and whether
    the bound holds, for A_j subset {0,...,m} in Z."""
    import math
    sizes: List[int] = [len(set(A)) for A in sets]
    n = len(sizes)
    p = n * math.log(m + 1) / math.log(n * m + 1)
    actual = len(iterated_minkowski_1d(sets))
    floor = math.prod(sizes) ** (1.0 / p)
    return actual, floor, actual + 1e-9 >= floor

